from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET
import os
p=Path('/home/user/workspace/c16/experiment_metrics.xlsx')
ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'; q=lambda t:f'{{{ns}}}{t}'
for prefix,uri in [('',ns),('r','http://schemas.openxmlformats.org/officeDocument/2006/relationships'),('xdr','http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing'),('x14','http://schemas.microsoft.com/office/spreadsheetml/2009/9/main'),('mc','http://schemas.openxmlformats.org/markup-compatibility/2006')]: ET.register_namespace(prefix,uri)
rows=[['Model_ID','Batch_Size','Latency_ms','Throughput_qps','Mem_GB'],['Model-A',16,110,82,12],['Model-B',16,124.0,78.5,16],['Model-C',32,95.0,94.0,16.0],['Model-D',32,130.0,76.0,20.0],['Model-E',64,88.0,109.5,24.0]]
with ZipFile(p) as z:
    files={i.filename:(i,z.read(i.filename)) for i in z.infolist()}
ss=ET.fromstring(files['xl/sharedStrings.xml'][1]); vals=[''.join(t.text or '' for t in si.iter(q('t'))) for si in ss.findall(q('si'))]; idx={v:i for i,v in enumerate(vals)}
for row in rows:
    for v in row:
        if isinstance(v,str) and v not in idx:
            si=ET.SubElement(ss,q('si')); ET.SubElement(si,q('t')).text=v; idx[v]=len(vals); vals.append(v)
root=ET.fromstring(files['xl/worksheets/sheet1.xml'][1]); sd=root.find(q('sheetData')); rowmap={int(r.get('r')):r for r in sd.findall(q('row'))}
for rn,rowvals in enumerate(rows,1):
    r=rowmap[rn]; cells={c.get('r'):c for c in r.findall(q('c'))}
    for cn,v in enumerate(rowvals,1):
        ref=f'{chr(64+cn)}{rn}'; c=cells.get(ref)
        if c is None: c=ET.Element(q('c'),{'r':ref,'s':'0'}); cells[ref]=c
        for child in list(c): c.remove(child)
        if isinstance(v,str): c.set('t','s'); ET.SubElement(c,q('v')).text=str(idx[v])
        else: c.set('t','n'); ET.SubElement(c,q('v')).text=str(v)
    def colnum(ref):
        n=0
        for ch in ''.join(filter(str.isalpha,ref)): n=n*26+ord(ch)-64
        return n
    ordered=sorted(cells.values(),key=lambda c:colnum(c.get('r')))
    for c in r.findall(q('c')): r.remove(c)
    for c in ordered:r.append(c)
ss.set('count',str(sum(1 for c in root.iter(q('c')) if c.get('t')=='s'))); ss.set('uniqueCount',str(len(vals)))
files['xl/sharedStrings.xml']=(files['xl/sharedStrings.xml'][0],ET.tostring(ss,encoding='UTF-8',xml_declaration=True))
files['xl/worksheets/sheet1.xml']=(files['xl/worksheets/sheet1.xml'][0],ET.tostring(root,encoding='UTF-8',xml_declaration=True))
tmp=p.with_suffix('.tmp.xlsx')
with ZipFile(tmp,'w') as z:
    for _,(info,data) in files.items(): z.writestr(info,data)
os.replace(tmp,p)
print('Patched A1:E6; all other cells preserved.')
